package wallet

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/torabian/fireback/modules/fireback"
	"github.com/torabian/fireback/modules/fireback/complexes"
	walletdefs "github.com/torabian/fireback/modules/finance/wallet/defs"
	"gorm.io/gorm"
)

// GatewayWebhookHandler is a hand-wired plain Gin route (registered in WalletModule.go
// as Any, not POST - see below - and not generated by emi, since a webhook has no caller
// session and needs the raw request body/headers for the gateway's own signature
// verification, neither of which fits emi's typed-action model). It:
//  1. Resolves the gateway by the :code path param and its registered GatewayAdapter.
//  2. Normalizes the transport into the one shape every GatewayAdapter.VerifyWebhook
//     expects, (rawBody []byte, headers http.Header), regardless of how this particular
//     gateway calls back: most gateways (Stripe, Przelewy24) POST a signed body; ZarinPal
//     has no server-to-server webhook at all - it redirects the browser via GET
//     (?Authority=...&Status=...) instead. For GET, the query string is marshalled into
//     a flat JSON object and used as rawBody, so the GatewayAdapter interface itself
//     never needs a second method for this - only what this handler feeds it differs.
//  3. Asks the adapter to verify+decode the normalized body into a GatewayEvent.
//  4. Records a walletEvent row unconditionally (audit trail, even for events we fail to
//     process or that don't match a known attempt).
//  5. On a matching, still-pending walletPaymentAttempt: credits the wallet through the
//     same applyLedgerEntry path purchase/adjustBalance use (using the attempt's own
//     idempotencyKey, so a duplicate webhook delivery can never double-credit), links the
//     resulting walletTransaction back onto the attempt, and marks it succeeded/failed.
//  6. Responds: if the attempt has a returnUrl (redirect-based gateways always set one -
//     see topup), redirects the browser there with ?status=succeeded|failed instead of
//     returning bare JSON. POST-webhook gateways' server-to-server caller simply ignores
//     a redirect response, so this is a no-op for them.
func GatewayWebhookHandler(c *gin.Context) {
	code := c.Param("code")

	var rawBody []byte
	if c.Request.Method == http.MethodGet {
		flat := map[string]string{}
		for k, v := range c.Request.URL.Query() {
			if len(v) > 0 {
				flat[k] = v[0]
			}
		}
		var err error
		rawBody, err = json.Marshal(flat)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "could not encode query params"})
			return
		}
	} else {
		var err error
		rawBody, err = io.ReadAll(c.Request.Body)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "could not read request body"})
			return
		}
	}

	tx := fireback.GetDbRef()
	var gateway walletdefs.WalletGatewayEntity
	if err := tx.First(&gateway, "code = ?", code).Error; err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "unknown gateway"})
		return
	}
	adapter, ok := GetGatewayAdapter(code)
	if !ok {
		c.JSON(http.StatusNotImplemented, gin.H{"error": "no adapter registered for gateway " + code})
		return
	}

	event, err := adapter.VerifyWebhook(c.Request.Context(), rawBody, c.Request.Header)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "webhook verification failed: " + err.Error()})
		return
	}

	now := complexes.XDate(time.Now().Format("2006-01-02"))
	evt := &walletdefs.WalletEventEntity{
		GatewayId:  gateway.Id,
		EventType:  event.EventType,
		Payload:    *complexes.JSONFrom(event.Payload),
		ReceivedAt: now,
	}
	if event.ExternalEventId != "" {
		evt.ExternalEventId.Set(&event.ExternalEventId)
	}

	var attempt walletdefs.WalletPaymentAttemptEntity
	findErr := tx.Preload("Wallet").First(&attempt, "gateway_reference = ?", event.GatewayReference).Error
	if findErr != nil {
		if !errors.Is(findErr, gorm.ErrRecordNotFound) {
			evt.ProcessingError.Set(strPtr(findErr.Error()))
		} else {
			evt.ProcessingError.Set(strPtr("no payment attempt found for gatewayReference " + event.GatewayReference))
		}
		tx.Create(evt)
		c.JSON(http.StatusOK, gin.H{"received": true})
		return
	}
	evt.PaymentAttemptId = attempt.Id

	if attempt.Status != "pending" && attempt.Status != "requires_action" {
		// Already terminal (e.g. a duplicate webhook delivery after we already
		// processed the first one) - record the event but don't reprocess.
		evt.Processed = true
		tx.Create(evt)
		finishWebhook(c, &attempt, attempt.Status == "succeeded")
		return
	}

	if !event.Succeeded {
		tx.Model(&attempt).Updates(map[string]any{
			"status":       "failed",
			"completed_at": now,
		})
		if event.FailureReason != "" {
			tx.Model(&attempt).Update("failure_reason", event.FailureReason)
		}
		evt.Processed = true
		tx.Create(evt)
		finishWebhook(c, &attempt, false)
		return
	}

	entry, err := applyLedgerEntry(tx, ledgerChange{
		WalletUniqueId: attempt.Wallet.UniqueId,
		Direction:      "credit",
		Amount:         attempt.Amount,
		Reason:         "topup",
		ReferenceType:  "walletPaymentAttempt",
		ReferenceId:    attempt.UniqueId,
		// Reusing the attempt's own idempotencyKey means a retried/duplicate webhook
		// delivery for the same attempt can never credit the wallet twice.
		IdempotencyKey: attempt.IdempotencyKey,
		CreatedBy:      "gateway:" + code,
	})
	if err != nil {
		evt.ProcessingError.Set(strPtr(err.Error()))
		tx.Create(evt)
		finishWebhook(c, &attempt, false)
		return
	}

	tx.Model(&attempt).Updates(map[string]any{
		"status":                "succeeded",
		"completed_at":          now,
		"wallet_transaction_id": entry.Id,
	})
	evt.Processed = true
	tx.Create(evt)
	finishWebhook(c, &attempt, true)
}

// finishWebhook responds once an attempt has been resolved and (possibly) processed. If
// the attempt has a returnUrl (redirect-based gateways like Przelewy24/ZarinPal/BLIK
// always set one via topup - see TopupImplementation.go), redirects the caller's browser
// there with the outcome appended; a server-to-server webhook caller (Stripe, P24's own
// notification) simply ignores a 302 response, so this is a safe no-op for those.
func finishWebhook(c *gin.Context, attempt *walletdefs.WalletPaymentAttemptEntity, succeeded bool) {
	status := "failed"
	if succeeded {
		status = "succeeded"
	}
	if returnUrl, ok := attempt.ReturnUrl.Get(); ok && returnUrl != nil && *returnUrl != "" {
		sep := "?"
		if strings.Contains(*returnUrl, "?") {
			sep = "&"
		}
		c.Redirect(http.StatusFound, *returnUrl+sep+"status="+status)
		return
	}
	c.JSON(http.StatusOK, gin.H{"received": true, "status": status})
}

func strPtr(s string) *string { return &s }
